  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Oritavancin, a lipoglycopeptide structurally closest to the query glycopeptide scaffold, showed only 5% CSF/plasma penetration in a rabbit Streptococcus pneumoniae meningitis model, directly demonstrating inadequate CNS access for this chemical class even with meningeal inflammation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Daptomycin, a large lipopeptide antibiotic, achieved only 5% CSF relative to serum in a rabbit pneumococcal meningitis model and undetectable CSF in a human case, supporting that large amphiphilic peptide antibiotics fail to reach meaningful CNS concentrations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Erythromycin, a large polar macrolide antibiotic, produced CSF concentrations of only 0.1–2.5 µg/mL versus serum peaks of 8–12 µg/mL in adults with meningitis, indicating poor blood-brain barrier penetration for large polar antibiotics despite inflammation.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a very large, highly polar glycopeptide-like antibiotic with multiple sugars, ionizable groups, and a lipophilic tail. Direct CSF-penetration experiments in meningitis models for the closest structural class (oritavancin) and other large antibiotics (daptomycin, erythromycin) show only 1–5% or lower CNS penetration, so meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct human CSF or brain exposure data for the exact query molecule.",
    "No unbound brain-to-plasma ratio or efflux-transporter measurement for the query.",
    "Meningitis can increase BBB permeability, but direct meningitis-model evidence for this compound class still shows poor penetration."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

